$result1 = mysqli_query($db1, $query1);
// Check for errors
if (!$result1) {
    die("Failed to execute query: " . mysqli_error($db1));
}
// Loop through the results and organize them in a nested array structure
while ($row1 = mysqli_fetch_assoc($result1)) {
    $category = $row1['category'];
    $subcategory = $row1['subcategory'];
    $item = $row1['item'];

    if (!isset($data[$category])) {
        $data[$category] = array();
    }

    if (!isset($data[$category][$subcategory])) {
        $data[$category][$subcategory] = array();
    }

    $data[$category][$subcategory][] = $item;
}
// Connect to the second database
