    die("Failed to execute query: " . mysqli_error($db2));
}
// Loop through the results and organize them in a nested array structure
while ($row2 = mysqli_fetch_assoc($result2)) {
    $category = $row2['category'];
    $subcategory = $row2['subcategory'];
    $item = $row2['item'];

    if (!isset($data[$category])) {
        $data[$category] = array();
    }

    if (!isset($data[$category][$subcategory])) {
        $data[$category][$subcategory] = array();
    }

    $data[$category][$subcategory][] = $item;
}
// Close the database connections
mysqli_close($db1);
mysqli_close($db2);
// Convert the data to JSON format
$json = json_encode($data);
// Display the data
echo $json;
?>
```
