```
func isPrime(_ number: Int) -> Bool {
    if number <= 1 {
        return false
    }
    for i in 2..<number {
        if number % i == 0 {
            return false
        }
    }
    return true
}
```
And here's a function that takes in an array of ingredients and a desired prime number sum, and returns two ingredients whose prime number sums add up to the desired value:
```
func findIngredientsForPrimeNumberSum(_ ingredients: [String], _ primeNumberSums: [Int], _ desiredSum: Int) -> (String, String)? {
    var primeSums = [Int: String]()
    for (index, ingredient) in ingredients.enumerated() {
        primeSums[primeNumberSums[index]] = ingredient
    }
    for (primeSum, ingredient) in primeSums {
        let complement = desiredSum - primeSum
        if primeSums[complement] != nil {
            return (ingredient, primeSums[complement]!)
        }
    }
    return nil
}
```
