    func prediction(image: CVPixelBuffer) throws -> MyImageClassifierModelOutput {
        let request = VNCoreMLRequest(model: model)
        try VNImageRequestHandler(cvPixelBuffer: image, options: [:]).perform([request])
        guard let results = request.results as? [VNClassificationObservation],
              let topResult = results.first else {
            throw NSError(domain: "com.example.MyApp", code: -1, userInfo: nil)
        }
        let output = MyImageClassifierModelOutput(classLabel: topResult.identifier, classProbability: topResult.confidence)
        return output
    }
}
struct MyImageClassifierModelOutput {
    let classLabel: String
    let classProbability: VNConfidence
}
