    y: Math.random() * canvas.height,
    fallSpeed: Math.random() * 2 + 1,
    windSpeed: Math.random() * 2 - 1,
    windDirection: Math.random() * 360
  };
  leaves.push(leaf);
}
```
5. Finally, we need to call the `draw` function to start the animation. For example:
```
draw();
```
