// Set the duration of the inhale, hold, and exhale phases
const inhaleDuration = 4;
const holdDuration = 2;
const exhaleDuration = 6;
// Set the total duration of the exercise
const totalDuration = inhaleDuration + holdDuration + exhaleDuration;
