  // Set the initial breath count to 0
  let breathCount = 0;
  // Set an interval to run every second for the duration of the exercise
  const interval = setInterval(() => {
    // Increment the breath count
    breathCount++;
    // Determine which phase of the exercise the user is in
    let phase;
    if (breathCount <= inhaleDuration) {
      phase = 'inhale';
    } else if (breathCount <= inhaleDuration + holdDuration) {
      phase = 'hold';
    } else {
      phase = 'exhale';
